#include <iostream>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    char start_char = line[0];
    std::string body = line.substr(1);
    size_t pos;
    while ((pos = body.find("dot")) != std::string::npos) {
        body.replace(pos, 3, ".");
    }
    std::string full_str = start_char + body;
    if (!full_str.empty() && full_str.back() == '.') {
        full_str.back() = 't'; // temporarily replace '.' with 't'
        full_str += "dot"; // append 'dot' to the string
        full_str.pop_back(); // remove the last 't' to keep the string consistent
    }
    start_char = full_str[0];
    std::string body_part = full_str.substr(1);
    size_t at_pos = body_part.find("at");
    if (at_pos != std::string::npos) {
        body_part.replace(at_pos, 2, "@");
    }
    if (!body_part.empty() && body_part.back() == '@') {
        body_part.back() = 't'; // temporarily replace '@' with 't'
        body_part += "at"; // append 'at'
        body_part.pop_back(); // remove the last 't'
    }
    std::cout << start_char << body_part << std::endl;
    return 0;
}
